import * as T from 'three';
import {clanShield} from './greek-battle-clans.mjs';
export const PALETTE=['#b74537','#d9803a','#86539c','#52795a','#d2ae38','#427caa'];
export const FACTIONS=['Sparta','Corinth','Macedon','Thebes','Argos','Athens'];
export const TYPES=['','Skirmishers','Peltasts','Javeliniers','Hoplites','Phalangists','Hypaspists','Light cavalry','Heavy cavalry','Chariots','Elephants'];
export const SETS={olive:{top:'#a7ac76',edge:'#79815e'},coast:{top:'#d8caa4',edge:'#9ba9a0'},clay:{top:'#c99470',edge:'#95664e'}};
const mats=new Map(),geos=new Map();
function mat(color){if(!mats.has(color))mats.set(color,new T.MeshStandardMaterial({color,roughness:.78}));return mats.get(color);}
function mesh(g,shape,color,x,y,z,sx,sy,sz){if(!geos.has(shape))geos.set(shape,shape==='ball'?new T.SphereGeometry(1,8,6):shape==='cyl'?new T.CylinderGeometry(1,1,1,10):shape==='cone'?new T.ConeGeometry(1,1,8):new T.BoxGeometry(1,1,1));const o=new T.Mesh(geos.get(shape),mat(color));o.position.set(x,y,z);o.scale.set(sx,sy,sz);o.castShadow=true;o.receiveShadow=true;o.userData.sharedGeometry=true;g.add(o);return o;}
function detailedUnit(v,c){const root=new T.Group(),col=PALETTE[c??0],bronze='#b3924e',skin='#d4a67c',linen='#e9ddbd',dark='#544235';const person=(g,y=0,heavy=v>=4)=>{mesh(g,'cone',col,0,y+.25,0,.14,.28,.14);mesh(g,'ball',skin,0,y+.47,0,.105,.12,.10);for(const x of [-.035,.035])mesh(g,'ball',dark,x,y+.485,-.094,.014,.016,.008);mesh(g,'ball',skin,0,y+.453,-.105,.019,.022,.018);for(const x of [-.14,.14]){const arm=mesh(g,'cyl',skin,x,y+.30,0,.035,.19,.035);arm.rotation.z=x>0?-.2:.2;}mesh(g,'box',col,0,y+.27,.105,.22,.30,.035);if(heavy){mesh(g,'ball',bronze,0,y+.545,-.015,.115,.075,.11);mesh(g,'box',bronze,0,y+.51,-.115,.021,.12,.018);for(const x of [-.086,.086])mesh(g,'box',bronze,x,y+.465,-.05,.026,.13,.055);mesh(g,'box',col,0,y+.62,-.015,.035,.10,.15);mesh(g,'box',linen,0,y+.31,0,.20,.19,.15);}for(const x of [-.06,.06])mesh(g,'cyl',dark,x,y+.08,0,.035,.16,.035);};
function horse(g,x=0,z=0,armored=false){const coat=armored?'#64503e':'#aa794e';mesh(g,'ball',coat,x,.35,z,.16,.21,.34);mesh(g,'ball',coat,x,.61,z-.24,.105,.21,.11);for(const dx of [-.10,.10])for(const dz of [-.22,.22])mesh(g,'cyl',dark,x+dx,.15,z+dz,.035,.30,.035);mesh(g,'box',col,x,.5,z,.25,.07,.24);if(armored)mesh(g,'box',bronze,x,.42,z-.21,.25,.3,.06);}
if(v===10){const grey='#8a928c';mesh(root,'ball',grey,0,.52,0,.32,.35,.45);mesh(root,'ball',grey,0,.65,-.4,.23,.25,.21);mesh(root,'cyl',grey,0,.35,-.55,.08,.45,.08);for(const x of [-.24,.24]){mesh(root,'ball',grey,x,.65,-.32,.14,.22,.08);for(const z of [-.27,.25])mesh(root,'cyl',grey,x,.19,z,.09,.38,.09);const tusk=mesh(root,'cone',linen,x*.6,.43,-.56,.045,.30,.045);tusk.rotation.x=-Math.PI/2;}mesh(root,'box',col,0,.82,0,.5,.08,.48);const rider=new T.Group();rider.scale.setScalar(.65);rider.position.y=.86;person(rider);root.add(rider);
}else if(v===9){horse(root,-.24,-.42);horse(root,.24,-.42);mesh(root,'box',bronze,0,.26,.42,.55,.12,.42);mesh(root,'box',col,0,.45,.23,.55,.28,.05);for(const x of [-.35,.35]){const w=mesh(root,'cyl',dark,x,.23,.45,.23,.05,.23);w.rotation.z=Math.PI/2;}const rider=new T.Group();rider.scale.setScalar(.8);rider.position.set(0,.31,.46);person(rider);root.add(rider);
}else{let py=0;if(v>=7){horse(root,0,0,v===8);py=.46;}person(root,py);if(v!==1){const shield=mesh(root,'cyl',v===2?bronze:col,-.16,py+.30,-.10,v===2?.105:.15,.035,v===2?.105:.15);shield.rotation.x=Math.PI/2;if(v===2){mesh(root,'ball',linen,-.16,py+.38,-.12,.06,.05,.025);}const len=v===5?1.1:v>=7?.8:.68;const spear=mesh(root,'cyl',dark,.16,py+len*.5,-.05,.012,len,.012);spear.rotation.x=-.25;const tip=mesh(root,'cone',bronze,.16,py+len,-.05-len*.12,.035,.12,.035);tip.rotation.x=-.25;if(v===3)mesh(root,'cyl',dark,.20,py+.35,-.04,.009,.64,.009);}else{const curve=new T.TorusGeometry(.16,.012,4,12,Math.PI),bow=new T.Mesh(curve,mat(dark));bow.position.set(.16,.31,-.04);bow.rotation.z=-Math.PI/2;root.add(bow);mesh(root,'cyl',linen,.16,.31,-.04,.004,.32,.004);}}
root.userData.unit={type:v,color:c};return root;}
export function hexBoard(set='olive',radius=1){const g=new T.Group(),s=SETS[set];const base=new T.Mesh(new T.CylinderGeometry(radius,radius,.18,6),mat(s.edge));base.position.y=-.09;base.receiveShadow=true;base.castShadow=true;g.add(base);const top=new T.Mesh(new T.CylinderGeometry(radius*.98,radius*.98,.035,6),mat(s.top));top.position.y=.012;top.receiveShadow=true;g.add(top);return g;}
const unitCache=new Map(),unitMaterial=new T.MeshStandardMaterial({vertexColors:true,roughness:.76});
export function unit(v,c,clan='crown',tint='#bd6489'){const key=v+':'+c+clan+tint;if(!unitCache.has(key)){const raw=detailedUnit(v,c);const emblem=clanShield(clan,tint);emblem.scale.setScalar(v>=9?.20:.20);emblem.position.set(v>=9?0:-.16,v>=9?.85:v>=7?.77:.30,v>=9?-.42:-.15);emblem.rotation.y=Math.PI;raw.add(emblem);raw.updateMatrixWorld(true);const positions=[],normals=[],colors=[];raw.traverse(o=>{if(!o.isMesh)return;const geo=o.geometry.index?o.geometry.toNonIndexed():o.geometry.clone();geo.applyMatrix4(o.matrixWorld);const p=geo.attributes.position,n=geo.attributes.normal;for(let i=0;i<p.count;i++){positions.push(p.getX(i),p.getY(i),p.getZ(i));normals.push(n.getX(i),n.getY(i),n.getZ(i));colors.push(o.material.color.r,o.material.color.g,o.material.color.b);}geo.dispose();});const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(positions,3));geo.setAttribute('normal',new T.Float32BufferAttribute(normals,3));geo.setAttribute('color',new T.Float32BufferAttribute(colors,3));unitCache.set(key,geo);}const mesh=new T.Mesh(unitCache.get(key),unitMaterial);mesh.castShadow=true;mesh.receiveShadow=true;mesh.userData.sharedGeometry=true;mesh.userData.unit={type:v,color:c};return mesh;}
export const figureCount=v=>v>=9?6:v>=7?12:24;
export function cardArmy(card,set='olive',clan='crown',tint='#bd6489'){const g=new T.Group(),v=card.v|| (card.t===2?8:card.t===3?3:6),c=card.c??0;g.add(hexBoard(set,1.12));const count=figureCount(v);for(let i=0;i<count;i++){const u=unit(v,c,clan,tint);const cols=v>=9?3:v>=7?4:6;u.scale.setScalar(v>=9?.22:v>=7?.25:.30);u.position.set(((i%cols)-(Math.min(cols,count)-1)/2)*.29,.035,(Math.floor(i/cols)-(Math.ceil(count/cols)-1)/2)*.37);g.add(u);}return g;}
const thumbs=new Map();let thumbRenderer;
export function thumbnail(card,set,clan='crown',tint='#bd6489'){const key=card.id+set+clan+tint;if(thumbs.has(key))return thumbs.get(key);if(!thumbRenderer){thumbRenderer=new T.WebGLRenderer({alpha:true,antialias:true});thumbRenderer.setSize(220,160);thumbRenderer.setPixelRatio(1);thumbRenderer.toneMapping=T.ACESFilmicToneMapping;}const scene=new T.Scene();scene.add(new T.HemisphereLight('#fff3db','#6f7259',2.5));const light=new T.DirectionalLight('#fff2d8',3);light.position.set(-3,7,4);scene.add(light);const army=cardArmy(card,set,clan,tint);scene.add(army);const camera=new T.PerspectiveCamera(30,220/160,.01,30);camera.position.set(2.7,3.4,4);camera.lookAt(0,.1,0);thumbRenderer.render(scene,camera);const url=thumbRenderer.domElement.toDataURL();thumbs.set(key,url);return url;}
